import { Group, Mesh, PlaneGeometry, Vector3 } from 'three';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new Group();
  const timelines = [];

  // 1. STAGE BACKGROUND / BASE PANEL (3.2 x 2.2 units)
  const panelW = 3.2;
  const panelH = 2.2;
  const panelGeo = new PlaneGeometry(panelW, panelH);

  // Background Custom Material with Engineered Gradient and Hairline Grid
  const panelMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.2,
    transparent: true,
    opacity: 1.0
  });

  // TSL Shader logic for custom background (engineered gradient + hairline grid)
  const color0 = vec3(0.078, 0.078, 0.102); // #14141a
  const color1 = vec3(0.043, 0.043, 0.063); // #0b0b10

  // Normalized UV shifted to center
  const uvc = uv().sub(0.5);
  const dist = uvc.length();
  const grad = mix(color0, color1, smoothstep(0.0, 0.7, dist));

  // Hairline grid at 0.25 unit pitch
  const gridPitchX = float(0.25 / panelW);
  const gridPitchY = float(0.25 / panelH);

  // TSL Grid calculations
  const gridLineX = smoothstep(0.005, 0.0, vec2(uv().x.mod(gridPitchX)).sub(0.001).abs());
  const gridLineY = smoothstep(0.005, 0.0, vec2(uv().y.mod(gridPitchY)).sub(0.001).abs());
  const gridActive = gridLineX.add(gridLineY).clamp(0.0, 1.0);

  // #e8ecf2 is vec3(0.91, 0.925, 0.95), apply 6% opacity
  const gridColor = vec3(0.91, 0.925, 0.95).mul(0.06).mul(gridActive);

  panelMat.colorNode = grad.add(gridColor);

  const panelMesh = new Mesh(panelGeo, panelMat);
  group.add(panelMesh);

  // 2. HAIRLINE BORDER (0.006-unit border #26262f / vec3(0.15, 0.15, 0.18))
  const borderGeo = new PlaneGeometry(panelW + 0.012, panelH + 0.012);
  const borderMat = new MeshBasicNodeMaterial({
    color: 0x26262f,
    wireframe: true,
    transparent: true,
    opacity: 0.8
  });
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.z = -0.001;
  group.add(borderMesh);

  // 3. GHOST PREVIEW GROUP (Left side of center: x = -0.65)
  const ghostGroup = new Group();
  ghostGroup.position.set(-0.65, 0.1, 0.01);

  // Wireframe card outline: 1.1w x 1.4h
  const outlineGeo = new PlaneGeometry(1.1, 1.4);
  const outlineMat = new MeshBasicNodeMaterial({
    color: 0xe8ecf2,
    wireframe: true,
    transparent: true,
    opacity: 0.3
  });
  const outlineMesh = new Mesh(outlineGeo, outlineMat);
  ghostGroup.add(outlineMesh);

  // Ghost dial circle: 0.55 diameter
  const dialRadius = 0.55 / 2;
  const dialGeo = new THREE.RingGeometry(dialRadius - 0.005, dialRadius, 32);
  const dialMat = new THREE.MeshBasicMaterial({
    color: 0xe8ecf2,
    transparent: true,
    opacity: 0.22,
    side: THREE.DoubleSide
  });
  const dialMesh = new Mesh(dialGeo, dialMat);
  dialMesh.position.set(0, 0.25, 0.005);
  ghostGroup.add(dialMesh);

  // Two ghost text bars: 0.7w x 0.06h
  const barGeo = new PlaneGeometry(0.7, 0.06);
  const barMat = new THREE.MeshBasicMaterial({
    color: 0xe8ecf2,
    transparent: true,
    opacity: 0.22
  });
  const bar1 = new Mesh(barGeo, barMat);
  bar1.position.set(0, -0.25, 0.005);
  const bar2 = new Mesh(barGeo, barMat);
  bar2.position.set(0, -0.38, 0.005);
  ghostGroup.add(bar1);
  ghostGroup.add(bar2);

  group.add(ghostGroup);

  // 4. COPY COLUMN + ACTION BUTTON (Right side of center: x = 0.6)
  const copyGroup = new Group();
  copyGroup.position.set(0.6, 0.5, 0.02);

  // Texts
  const texts = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headText = texts.find(t => t.role === 'headline')?.text ?? "Your ledger is empty.";
  const bodyText = texts.find(t => t.role === 'body')?.text ?? "Commissioned pieces and saved references will appear here once you begin.";
  const ctaText = texts.find(t => t.role === 'cta-label')?.text ?? "BROWSE THE COLLECTION";

  // Headline
  const hNode = ctx.fontAtlas.createText(headText, {
    fontSize: 34 * 0.0055, // Responsive scaling to scene units
    color: '#e8ecf2',
    align: 'left',
    maxWidthPx: 320
  });
  hNode.position.set(-0.6, 0, 0);
  copyGroup.add(hNode);

  // Body
  const bNode = ctx.fontAtlas.createText(bodyText, {
    fontSize: 13 * 0.006,
    color: '#e8ecf2',
    align: 'left',
    maxWidthPx: 300
  });
  bNode.position.set(-0.6, -0.35, 0);
  copyGroup.add(bNode);

  // ACCENT CTA BUTTON (1.5w x 0.36h, vertical gradient #ff4450 -> #c1121f)
  const ctaGroup = new Group();
  ctaGroup.position.set(0.15, -0.8, 0);

  const buttonGeo = new PlaneGeometry(1.5, 0.36);
  const buttonMat = new MeshStandardNodeMaterial({
    roughness: 0.4,
    metalness: 0.1,
    transparent: true,
    opacity: 1
  });

  // Gradient TSL for button (#ff4450 to #c1121f)
  const btnCol0 = vec3(1.0, 0.266, 0.313);
  const btnCol1 = vec3(0.757, 0.07, 0.121);
  buttonMat.colorNode = mix(btnCol1, btnCol0, uv().y);
  buttonMat.emissiveNode = vec3(1.0, 0.165, 0.22).mul(0.15); // Edge emissive intensity emulation

  const buttonMesh = new Mesh(buttonGeo, buttonMat);
  ctaGroup.add(buttonMesh);

  // CTA Text (Ink / Dark Label)
  const labelNode = ctx.fontAtlas.createText(ctaText, {
    fontSize: 13 * 0.0052,
    color: '#16161d',
    align: 'center'
  });
  labelNode.position.set(0, -0.04, 0.01);
  ctaGroup.add(labelNode);

  copyGroup.add(ctaGroup);
  group.add(copyGroup);

  // 5. LIGHTING (Local Key Light to catch specular structure as per Spec)
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(4, 3, 5);
  keyLight.target = panelMesh;
  group.add(keyLight);

  // Rim Light containing accent hue
  const rimLight = new THREE.DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-4, -2, 2);
  group.add(rimLight);

  // 6. ANIMATION & INTERACTIVE STATE
  // Idle Breathing of ghost group (opacity 0.24 -> 0.34 over 2400ms)
  const breatheTl = gsap.timeline({ repeat: -1, yoyo: true });
  breatheTl.to(ghostGroup.scale, {
    x: 1.02,
    y: 1.02,
    duration: 2.4,
    ease: "power1.inOut"
  });
  timelines.push(breatheTl);

  // Mount fade-up transition (opacity 0 -> 1 and y +0.2 -> 0 over 500ms)
  group.position.y += 0.2;
  const mountTl = gsap.timeline();
  mountTl.to(group.position, {
    y: 0,
    duration: 0.5,
    ease: "power2.out"
  });
  timelines.push(mountTl);

  // Interactive Button Press Handlers (Press scale 1.0 -> 0.97 over 120ms)
  group.userData.handlers = {
    onClick: () => {
      gsap.to(ctaGroup.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: "back.out(1.7)",
        yoyo: true,
        repeat: 1
      });
      ctx.emit('navigate', { to: 'hub-collection' });
    },
    onPointerOver: () => {
      gsap.to(ctaGroup.scale, { x: 1.03, y: 1.03, duration: 0.2 });
    },
    onPointerOut: () => {
      gsap.to(ctaGroup.scale, { x: 1.0, y: 1.0, duration: 0.2 });
    }
  };

  // 7. CLEANUP
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    panelGeo.dispose();
    panelMat.dispose();
    borderGeo.dispose();
    borderMat.dispose();
    outlineGeo.dispose();
    outlineMat.dispose();
    dialGeo.dispose();
    dialMat.dispose();
    barGeo.dispose();
    barMat.dispose();
    buttonGeo.dispose();
    buttonMat.dispose();
  };

  return group;
}
